state.shards.forEach((s,i)=>{c.save();c.shadowColor='#e8b37e';c.shadowBlur=20;diamond(c,s.x,s.y+Math.sin(state.time*3+i)*3,9,'#f4c28e');c.restore();c.strokeStyle='#71573d';c.beginPath();c.arc(s.x,s.y,19,0,Math.PI*2);c.stroke()});
