function addTranslation(english,arabic){const item={english,arabic,at:Date.now()};if(transcript.at(-1)?.english===english)return;transcript.push(item);$('#translationResult').textContent=arabic;$('#captureSubtitle').textContent=arabic;$('#transcript').replaceChildren();transcript.slice().reverse().forEach(x=>{const row=document.createElement('div'),a=document.createElement('span'),b=document.createElement('span');a.dir='ltr';a.textContent=x.english;b.dir='rtl';b.textContent=x.arabic;row.append(a,b);$('#transcript').append(row)})}
