async function ocr(blob,signal,session){
if(!blob||blob.size>5*1024*1024)throw Error(t('اختر صورة أقل من ٥ ميغابايت.','Choose an image smaller than 5 MB.'));
const body=new FormData();body.append('file',blob,'screen.png');
const r=await api('/api/ocr?region='+encodeURIComponent($('#ocrRegion').value),{method:'POST',body,signal});
if(session!==undefined&&session!==captureSession)return;
if(r.english)addTranslation(r.english,r.arabic);else $('#captureSubtitle').textContent='';
$('#ocrStatus').textContent=r.english?t('تمت الترجمة خلال ','Translated in ')+((r.elapsed_ms||0)/1000).toFixed(1)+t(' ثانية',' seconds'):t('لم يُعثر على نص واضح. جرّب تغيير منطقة القراءة.','No legible text found. Try a different recognition area.');
}
$('#ocrButton').onclick=()=>task($('#ocrButton'),async()=>{requireCapability('ocr');const file=$('#ocrFile').files[0];if(!file)throw Error(t('اختر لقطة شاشة أولاً','Select a screenshot first'));await ocr(file)},$('#ocrStatus'));
let captureSession=0,captureAbort=null;
function stopCapture(){captureSession++;captureAbort?.abort();captureAbort=null;captureStream?.getTracks().forEach(track=>track.stop());captureStream=null;clearTimeout(captureTimer);ocrBusy=false;$('#captureVideo').srcObject=null;$('#captureVideo').hidden=true;$('#capturePlaceholder').hidden=false;$('#stopCapture').disabled=true;$('#capture').disabled=false;$('#captureSubtitle').textContent='';if($('#cropGuide'))$('#cropGuide').hidden=true;}
async function readCapture(session){if(!captureStream||session!==captureSession)return;const v=$('#captureVideo');if(v.videoWidth){ocrBusy=true;try{const c=document.createElement('canvas');c.width=Math.min(v.videoWidth,1600);c.height=Math.round(c.width*v.videoHeight/v.videoWidth);c.getContext('2d').drawImage(v,0,0,c.width,c.height);const b=await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(session!==captureSession)return;captureAbort=new AbortController();await ocr(b,captureAbort.signal,session)}catch(e){if(session!==captureSession||e.name==='AbortError')return;$('#ocrStatus').textContent=e.message;stopCapture()}finally{if(session===captureSession)ocrBusy=false}}if(captureStream&&session===captureSession)captureTimer=setTimeout(()=>readCapture(session),3000);}
$('#capture').onclick=()=>task($('#capture'),async()=>{requireCapability('ocr');server();if(!navigator.mediaDevices?.getDisplayMedia)throw Error(t('مشاركة الشاشة غير متاحة هنا. استخدم لقطة شاشة.','Screen sharing unavailable here. Upload a screenshot.'));stopCapture();const session=captureSession;try{const source=await navigator.mediaDevices.getDisplayMedia({video:true,audio:false});if(session!==captureSession){source.getTracks().forEach(track=>track.stop());return}captureStream=source;$('#captureVideo').srcObject=source;$('#captureVideo').hidden=false;$('#capturePlaceholder').hidden=true;$('#stopCapture').disabled=false;source.getVideoTracks()[0].onended=()=>{if(session===captureSession)stopCapture()};await $('#captureVideo').play();updateCropGuide();readCapture(session)}catch(e){stopCapture();if(e.name==='NotAllowedError')throw Error(t('لم تبدأ المشاركة. اختر نافذة واسمح بالتقاطها لتفعيل الترجمة.','Sharing did not start. Choose a window and allow capture.'));throw e}});$('#stopCapture').onclick=stopCapture;
function srtTime(ms){const v=Math.max(0,ms),h=Math.floor(v/3600000),m=Math.floor(v/60000)%60,s=Math.floor(v/1000)%60;return [h,m,s].map(n=>String(n).padStart(2,'0')).join(':')+','+String(v%1000).padStart(3,'0')}$('#exportSrt').onclick=()=>{if(!transcript.length)return toast(t('ترجم نصاً أولاً','Translate something first'));const start=transcript[0].at;const data=transcript.map((x,i)=>{const a=x.at-start,b=Math.min(a+4000,transcript[i+1]?transcript[i+1].at-start:a+4000);return `${i+1}\n${srtTime(a)} --> ${srtTime(b)}\n${x.arabic}\n`}).join('\n');const url=URL.createObjectURL(new Blob([data],{type:'application/x-subrip;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='parallel-arabic.srt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
function leaveRoom(){if(socket){socket.close();socket=null}remotePlayers={};$('#roomStatus').textContent=t('غير متصل','Not connected')}$('#leaveRoom').onclick=leaveRoom;$('#joinRoom').onclick=()=>{try{const room=$('#roomCode').value.trim();if(!/^[a-zA-Z0-9_-]{1,40}$/.test(room))throw Error(t('استخدم أحرفاً إنجليزية وأرقاماً وشرطات لرمز الغرفة','Room code: use letters, digits, underscores or hyphens'));const base=server().replace(/^http/,'ws');leaveRoom();const ws=new WebSocket(base+'/ws/'+encodeURIComponent(room));socket=ws;ws.onopen=()=>ws.send(JSON.stringify({type:'auth',token:$('#apiToken').value.trim()}));ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.type==='ready'){$('#roomStatus').textContent=t('متصل بالغرفة: ','Connected to room: ')+room;toast(t('تم الاتصال بالغرفة المشتركة','Shared room connected'))}if(m.type==='positions')remotePlayers=m.players;if(m.type==='event')pulse()};ws.onerror=()=>{$('#roomStatus').textContent=t('تعذر الاتصال بالخادم','Unable to connect')};ws.onclose=()=>{if(socket===ws){socket=null;remotePlayers={};$('#roomStatus').textContent=t('انقطع الاتصال','Disconnected')}}}catch(e){toast(e.message)}};setInterval(()=>{if(socket?.readyState===1)socket.send(JSON.stringify({type:'position',x:state.player.x,y:state.player.y,z:0}))},100);
function stopStream(){peer?.close();peer=null;$('#stream').srcObject=null;$('#stream').hidden=true;streaming=false;$('.game-top').hidden=false;$('.game-bottom').hidden=false;$('#pause').disabled=false;$('#game').hidden=false;$('#startOverlay').hidden=started;$('#subtitle').hidden=!$('#subs').checked;$('#rendererLabel').textContent=(lang==='ar'?ar:en).renderer}$('#stopStream').onclick=stopStream;$('#startStream').onclick=()=>task($('#startStream'),async()=>{requireCapability('stream');stopStream();const config=await api('/api/rtc-config');peer=new RTCPeerConnection(config);peer.addTransceiver('video',{direction:'recvonly'});peer.ontrack=e=>{$('#stream').srcObject=new MediaStream([e.track]);$('#stream').hidden=false;$('#game').hidden=true;$('#startOverlay').hidden=true;$('#subtitle').hidden=true;streaming=true;$('.game-top').hidden=true;$('.game-bottom').hidden=true;$('#pause').disabled=true;running=false;view('arena');$('#rendererLabel').textContent=t('بث فيديو من الخادم','Server video stream')};await peer.setLocalDescription(await peer.createOffer());if(peer.iceGatheringState!=='complete')await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('ICE gathering timeout')),15000);peer.addEventListener('icegatheringstatechange',()=>{if(peer?.iceGatheringState==='complete'){clearTimeout(timer);resolve()}})});const answer=await api('/api/offer',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(peer.localDescription)});await peer.setRemoteDescription(answer);peer.onconnectionstatechange=()=>{if(peer?.connectionState==='failed'){stopStream();toast(t('فشل البث؛ راجع إعدادات TURN والشبكة','Stream failed; check TURN and network configuration'))}}});
